    const bot = [0, YC - R + 1.2, 0];
    for (let k = 0; k < 3; k++){ const a = k/3*TAU + 0.3, f = [Math.cos(a)*7.5, 0.4, Math.sin(a)*7.5]; barP(B.p(DARK), f, [Math.cos(a)*1.2, 6.2, Math.sin(a)*1.2], 1.1, 0.9); boxP(B.p(STONE), 2.4, 1.2, 2.4, f[0], -0.4, f[2], a); }
    LCylE(g, 1.4, 1.8, YC - 6, 0, 6, 0, DARK, 10);
    // the pool: water, granite bulkhead, the fountain jets aimed inward over the pedestal
    const P = F.pool, pc = [P.reduce((s, p) => s + p[0], 0)/P.length, P.reduce((s, p) => s + p[1], 0)/P.length];
    flatP(B.p(WATER), P, 0.25);
    for (let i = 0; i < P.length; i++){ const a = P[i], b = P[(i+1) % P.length], [nx, nz] = outN(P, i);
      quadP(B.p(STONE), [a[0], -0.5, a[1]], [b[0], -0.5, b[1]], [b[0], 0.75, b[1]], [a[0], 0.75, a[1]]);
      quadP(B.p(STONE), [a[0], 0.75, a[1]], [b[0], 0.75, b[1]], [b[0] + nx*1.4, 0.75, b[1] + nz*1.4], [a[0] + nx*1.4, 0.75, a[1] + nz*1.4]); }
